from AlgorithmImports import *


class TwoSlotEquityStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_close = {}
        self.previous_spy_sma = None
        self.previous_aapl_rsi = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.rsi_threshold = 70

    def OnData(self, data: Slice):
        current_bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.ContainsKey(symbol):
                self._update_available_state(data)
                return

            bar = data[symbol]
            if bar is None:
                self._update_available_state(data)
                return

            current_bars[ticker] = bar

        self._update_available_state(data)

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or self.previous_spy_sma is None
            or self.previous_aapl_rsi is None
            or "AAPL" not in self.previous_close
        ):
            self.previous_spy_sma = float(self.spy_sma.Current.Value)
            self.previous_aapl_rsi = float(self.aapl_rsi.Current.Value)
            return

        spy_close = float(current_bars["SPY"].Close)
        aapl_close = float(current_bars["AAPL"].Close)
        spy_sma = float(self.spy_sma.Current.Value)
        aapl_rsi = float(self.aapl_rsi.Current.Value)

        spy_crosses_below = (
            float(self.previous_close["SPY"]) <= self.previous_spy_sma
            and spy_close > 0
            and spy_close < spy_sma
        )

        spy_crosses_above = (
            float(self.previous_close["SPY"]) <= self.previous_spy_sma
            and spy_close > spy_sma
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if (
            self.strategy_b_lot > 0
            and self.previous_aapl_rsi <= self.rsi_threshold
            and aapl_rsi > self.rsi_threshold
        ):
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            quantity = int(target_value / spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

        self.previous_spy_sma = spy_sma
        self.previous_aapl_rsi = aapl_rsi

    def _update_available_state(self, data: Slice):
